<script setup lang="ts">
import { computed } from 'vue'
import type { Conflict } from '../drafts'
const props=defineProps<{value?:Conflict;recovery?:boolean}>();defineEmits<{reload:[];keep:[]}>()
const labels:Record<string,string>={name:'名称',title:'标题',content:'内容',description:'说明',status:'状态',progress:'进度',assignee:'负责人',owner:'负责人',plan_start:'计划开始',plan_end:'计划结束',root_cause:'根因',solution:'解决方案',verify_result:'验证结果',parent_id:'上级任务',project_id:'项目',code:'编号',customer:'客户',phase:'阶段',manager:'项目负责人',start_date:'开始日期',end_date:'结束日期',estimate_hours:'预计工时',priority:'优先级',location:'地点',type:'记录类型',tags:'标签',attachments:'附件',period_type:'日志周期',log_date:'日志日期',meeting_date:'会议日期',attendees:'参会人',due_at:'期望解决日期',source:'问题来源',severity:'严重程度',rejection_reason:'驳回原因',work_date:'工作日期',minutes:'分钟数',hours:'小时数',note:'工作说明',task_id:'关联任务',reminder_due_at:'提醒时间',reminder_local:'提醒时间',due_local:'提醒时间'}
const fields=computed(()=>props.value?Object.keys(props.value.local).filter(k=>k!=='version'&&JSON.stringify(props.value!.local[k])!==JSON.stringify(props.value!.remote[k])):[])
function text(value:unknown){return typeof value==='object'?JSON.stringify(value):String(value??'（空）')}
</script>
<template><section v-if="value" class="conflict-notice" role="alert"><h3>{{recovery?'草稿与当前数据库版本不同':'数据库内容已更新，本次没有覆盖'}}</h3><p>{{recovery?'对比后再恢复草稿。恢复只更改编辑区，核对后需要显式保存。':'对比后可保留本地草稿，或载入数据库的新内容。重新编辑后再保存。'}}</p><div class="conflict-table"><table><thead><tr><th>字段</th><th>你的修改</th><th>数据库新内容</th></tr></thead><tbody><tr v-for="key in fields" :key="key"><td>{{labels[key]||key}}</td><td>{{text(value.local[key])}}</td><td>{{text(value.remote[key])}}</td></tr></tbody></table></div><div class="row-actions"><button type="button" class="button subtle small" @click="$emit('keep')">{{recovery?'恢复草稿继续核对':'保留本地草稿'}}</button><button type="button" class="button primary small" @click="$emit('reload')">{{recovery?'继续使用数据库内容':'载入新数据'}}</button></div></section></template>
